import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cnt = {}
    for tok in data[1:1 + n]:
        v = int(tok)
        cnt[v] = cnt.get(v, 0) + 1
    best = None
    for v, c in cnt.items():
        if best is None or c > cnt[best] or (c == cnt[best] and v < best):
            best = v
    print(best)

main()

